'use strict';

// MODULES //

var arraylikefcn = require( '@stdlib/assert/tools/array-like-function' );
var isSymbol = require( '@stdlib/plot/base/assert/is-symbol' );


// MAIN //

/**
* Tests whether an input value is an array of symbols.
*
* @name isSymbolArray
* @type {Function}
* @param {*} value - value to test
* @returns {boolean} boolean indicating whether an input value is an array of symbols
*
* @example
* var bool = isSymbolArray( [ 'o' ] );
* // returns true
*
* bool = isSymbolArray( {} );
* // returns false
*
* bool = isSymbolArray( 'foo' );
* // returns false
*/
var isSymbolArray = arraylikefcn( isSymbol );


// EXPORTS //

module.exports = isSymbolArray;
